#include "session_tick_grid_candidate.h"
#include <iostream>
int main(){try{static_assert(sizeof(void*)==8,"x64 required");if(sessionTickGridCandidate(100,-333,3)!=std::vector<int32_t>({100,-233,-566}))throw std::runtime_error("backward grid");if(sessionTickGridCandidate(0,333,4)!=std::vector<int32_t>({0,333,666,999}))throw std::runtime_error("forward grid");size_t rejected=0;auto reject=[&](int32_t start,int32_t step,size_t count){bool bad=false;try{sessionTickGridCandidate(start,step,count);}catch(const std::runtime_error&){bad=true;}if(!bad)throw std::runtime_error("bad tick grid accepted");++rejected;};reject(INT32_MAX,1,2);reject(INT32_MIN,-1,2);reject(0,0,2);reject(0,1,0);reject(0,1,10001);std::cout<<"x64 session tick grid passed forward=exact backward=exact invalid_or_overflow_rejected="<<rejected<<" seconds_scale=unverified\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
